      const mean = xs.reduce((a, b) => a + b, 0) / xs.length
      const ss = xs.reduce((a, b) => a + (b - mean) ** 2, 0)
      const pop = ss / xs.length
      const sample = xs.length > 1 ? ss / (xs.length - 1) : null
