/** Tools that take a pasted number series. */
/**
 * Every tool, with its per-locale slugs resolved.
 *
 * Merged rather than mutated: `slugs.generated.ts` is data, this is the one
 * place the two are joined, and no consumer has to know the split exists —
 * `tool.slugs` is complete for all 21 locales by the time anyone reads it.
 * The authored `en`/`it` values win, so a hand-written slug can never be
 * overwritten by a regenerated one.
 */
export const TOOLS: ToolDef[] = AUTHORED_TOOLS.map((tool) => ({
  ...tool,
  slugs: { ...(LOCALE_SLUGS[tool.id] ?? {}), ...tool.slugs },
}))

export const SERIES_TOOLS: readonly string[] = TOOLS.filter((t) => t.series).map((t) => t.id)

/** Every slug, in every locale, mapped to its tool. */
export function slugIndex(): Map<string, { tool: ToolDef; locale: string }> {
  const index = new Map<string, { tool: ToolDef; locale: string }>()
  for (const tool of TOOLS) {
    for (const [locale, slug] of Object.entries(tool.slugs)) {
      index.set(`${locale}:${slug}`, { tool, locale })
    }
  }
  return index
}

/**
 * A route param as the app compares it: DECODED.
 *
 * Next hands `[slug]` to the page percent-ENCODED, and the registry stores
 * every slug decoded (`src/fields/slug.ts`'s rule; slugs.test.ts pins the
 * round trip). Until 2026-09-23 the tools page compared the two raw, so
 * `roi計算ツール` arrived as `roi%E8%A8%88…`, matched nothing, and every
 * tool page in the eight non-Latin locales — zh, tc, ar, uk, th, he, ko,
 * ja, 328 pages — was a 404 under an index that linked to it. Every other
 * dynamic route in the app already decodes (the main site's
 * `[...segments]`, help, the quarterly issues); this is the same rule in
 * one place. A malformed escape is not a slug: it falls through as-is and
 * matches nothing, so the page 404s it like any unknown slug.
 */
export function decodeSlug(raw: string): string {
  try {
    return decodeURIComponent(raw)
  } catch {
    return raw
  }
}

/** The tool a slug names in a locale, falling back to the English slug. */
export function toolBySlug(locale: string, slug: string): ToolDef | undefined {
  return (
    TOOLS.find((t) => t.slugs[locale] === slug) ??
    TOOLS.find((t) => t.slugs.en === slug)
  )
}

/** A tool's slug in a locale — its English slug where it has no own. */
export const slugFor = (tool: ToolDef, locale: string): string => tool.slugs[locale] ?? tool.slugs.en

/**
 * Look a tool up by id.
 *
 * This exists so the CLIENT can do the lookup. A `ToolDef` carries
 * `compute`, a function, and React cannot serialise a function across
 * the server/client boundary — passing the whole object into
 * `<Calculator>` fails the production build with "Functions cannot be
 * passed directly to Client Components", though `next dev` renders it
 * happily. The server passes the id; the client resolves it here.
 */
export function toolById(id: string): ToolDef | undefined {
  return TOOLS.find((t) => t.id === id)
}

export const CATEGORIES = ['finance', 'inventory', 'sales', 'marketing', 'operations', 'data'] as const
